infra.infra/prod/main.tf:
data "aws_secretsmanager_secret" "iot" {
  name = "fargate/iot-client-credentials"
}

resource "aws_sns_topic" "events" {
  name = "asset-events"
}

resource "aws_iam_role" "lambda" {
  name               = "worker-lambda"
  assume_role_policy = "{}"
}

data "aws_iam_policy_document" "lambda" {
  statement {
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.events.arn]
  }
  statement {
    actions   = ["s3:GetObject", "s3:PutObject"]
    resources = ["arn:aws:s3:::exports-prod/*"]
  }
}

resource "aws_iam_role_policy" "lambda" {
  role   = aws_iam_role.lambda.id
  policy = data.aws_iam_policy_document.lambda.json
}

resource "aws_lambda_function" "worker" {
  function_name = "worker"
  role          = aws_iam_role.lambda.arn
  environment {
    variables = {
      TOPIC_ARN          = aws_sns_topic.events.arn
      EXPORT_BUCKET_NAME = "exports-prod"
    }
  }
}

resource "aws_iam_role" "task" {
  name               = "gateway-task"
  path               = "/system/ecs/"
  assume_role_policy = "{}"
}

resource "aws_iam_role_policy" "task" {
  role = aws_iam_role.task.name
  policy = jsonencode({
    Statement = [{
      Effect   = "Allow"
      Action   = ["secretsmanager:GetSecretValue"]
      Resource = [data.aws_secretsmanager_secret.iot.arn]
    }]
  })
}

